class LwdElement extends HTMLElement {
  constructor(root, attrs = {}) {
    super()
    this.attachShadow({ mode: 'open' });
    this.shadowRoot.append(this.styleElement = document.createElement('style'))
    this.root = root

    this.constructor.observedAttributes.forEach((observedAttribute) => {
      Object.defineProperty(this, LwdElement.attributeToProperty(observedAttribute), {
        get: this.createGetter(observedAttribute),
        set: this.createSetter(observedAttribute),
        // writable: true, 
        configurable: true
      });
    })

    Object.entries(attrs).forEach(([key, value]) => (this[key] = value));
  }

  static get observedAttributes() {
    return ['link']
  }
  get reRenderOnChange() {
    return []
  }

  connectedCallback() {
    this.ready = true
    this.render();
  }

  render() {
    this.styleElement.innerHTML = this.styleSheet;
    if (!!this.root) this.shadowRoot.append(this.root)
  }

  get styleSheet() {
    return `
:host{
  position: relative;
}
*{
      box-sizing: inherit;
      font-family: inherit;
      font-size: inherit;
}
    `
  }

  attributeChangedCallback(name, oldValue, newValue) {
    // console.log('attributeChangedCallback', this, name, oldValue, newValue)
    if (oldValue == newValue) return;
    if (!this.ready) return;

    this.dispatchEvent(new CustomEvent('attribute-changed', { detail: { name, oldValue, newValue }, }));

    if (this.reRenderOnChange.includes(name)) this.render();
  }

  disconnectedCallback() {
    this.ready = false
  }

  static attributeToProperty(attributeName) {
    // Remove _
    let propertyName = attributeName.replaceAll('_', '')
    // Convert from kebab-case to camelCase
    propertyName = propertyName.split('-').map((str, i) => i === 0 ? str : str[0].toUpperCase() + str.slice(1)).join('')
    return propertyName
  }

  createGetter(attributeName) {
    const propertyName = LwdElement.attributeToProperty(attributeName)
    const definedGetter = this.__lookupGetter__(propertyName)
    if (definedGetter) return definedGetter;
    if (attributeName[0] === '_') return () => this[`_${propertyName}`];
    return () => this.getAttribute(attributeName);
  }

  createSetter(attributeName) {
    const propertyName = LwdElement.attributeToProperty(attributeName)
    const definedSetter = this.__lookupSetter__(propertyName)

    if (definedSetter) return definedSetter;
    if (attributeName[0] === '_') {
      return (value) => {
        const oldValue = this[`_${propertyName}`]
        this[`_${propertyName}`] = value
        this.attributeChangedCallback(attributeName, oldValue, value)
      }
    }
    return (value) => this.setAttribute(attributeName, value);
  }
}
class LwdSlot extends HTMLSlotElement {
  constructor(props ={}){
    super()
    Object.entries(props).forEach(([key, value]) => (this[key] = value));
  }
}
customElements.define('lwd-slot', LwdSlot, {extends: 'slot'});class LwdButton extends LwdElement  {
  constructor(props = {}) {
    super(undefined, props);
    this.shadowRoot.append(new LwdSlot())
    this.type ||= 'primary'
  }

  static get observedAttributes() {
    return [...super.observedAttributes, 'value', 'type', 'name'];
  }

  get styleSheet() {
    return `${super.styleSheet}
:host{
  display: inline-flex;
  justify-content: space-around;
  align-items: center;
  padding: 2px 0.5rem;
  border-radius: 0.4rem;
  cursor: pointer;
}
:host([type=primary]){
  background: var(--primary-bg, white);
  color: var(--primary-color, black);
  border: var(--primary-border, none);
}
:host([type=outline]){
  background: var(--outline-bg, none);
  color: var(--outline-color, white);
  border: var(--outline-color, white) var(--outline-border, solid 2px);
}
:host([type=ghost]){
  background: var(--ghost-bg, #88888820);
  color: var(--ghost-color, white);
  border: var(--ghost-border, none);
}
    `
  }
}

customElements.define('lwd-button', LwdButton);
class LwdGalery extends LwdElement  {
  constructor(props = {}) {
    // super(document.createElement('div'), props);
    // this.root.append(new LwdSlot({name: 'image'}))
    super(undefined, props);
    this.shadowRoot.append(new LwdSlot({name: 'image'}))
    this.shadowRoot.append(this.focusSection = new LwdSection({className: 'focus'}))
    this.focusSection.append(this.focusSection.image = new LwdImage())

    this.focusSection.ondblclick = () => {this.focusSection.classList.remove('active'); this.focusSection.image.src=undefined;}

    this.addEventListener('attribute-changed', ({ detail: { name, newValue } }) => name == '_focus-image' ? this.renderFocus() : '')

  }

  static get observedAttributes() {
    return [...super.observedAttributes, '_image-list', '_focus-image'];
  }
  get reRenderOnChange() {
    return [...super.reRenderOnChange, '_image-list'];
  }

  renderFocus(){
    this.focusSection.image.src = this.focusImage.srcOriginal
    this.focusSection.classList.add('active')
  }


  render() {
    super.render()
    this.querySelectorAll('[slot=image]').forEach((el ) => el.remove())
    console.log('LwdGalery render', this.imageList)
    this.imageList?.forEach((image) => {
      this.append(new LwdImage({...image, src: image.srcThumb, slot: 'image', onclick: () => this.focusImage = image}))
    });
  }

  get styleSheet() {
    return `${super.styleSheet}
:host{
  display: grid;
  max-height: 100%;
  max-width: 100%;
  height: 100%;
  width: 100%;
  --image-width: ${this.imageWidth || '134px'};
  --image-height: ${this.imageHeight || '140px'};
  grid-template-columns: repeat(auto-fill, var(--image-width));
  grid-template-rows: repeat(auto-fill, var(--image-height));
  grid-gap: 8px;
  align-items: center;
  justify-items: center;
  justify-content: center;
  overflow: auto;
  scrollbar-width: none;
}

  .focus{
    display: none;
    position: fixed;
    width: 100vw;
    height: 100vh;
    top: 0;
    left: 0;
    --image-height: 100vh;
    --image-width: 100vw;
    background-color: var(--bg-1)
  }

  .focus.active{
    display: flex;
    justify-content: center;
    align-items: center;
  }
`
  }
}

customElements.define('lwd-galery', LwdGalery);
class LwdImage extends LwdElement  {
  constructor(props = {}) {
    const frame = document.createElement('div')
    const image = document.createElement('img')
    frame.append(image)
    super(frame, props);
    this.frame = this.frame
    this.image = this.image
  }

  static get observedAttributes() {
    return [...super.observedAttributes, 'src', 'frame-color'];
  }

  get src(){
    return this.getAttribute('img')
  }
  set src(value){
    this.setAttribute('src', value)
    this.root.querySelector('img').src = value
  }

  get frameColor(){
    return this.getAttribute('frame-color')
  }
  set frameColor(value){
    if(!!value){
      this.setAttribute('frame-color', value)
      this.root.classList.add('frame')
    }else{
      this.removeAttribute('frame-color')
      this.root.classList.remove('frame')
    }
  }

  get styleSheet() {
    return `${super.styleSheet}
:host{
  display: block;
  max-height: 100%;
  max-width: 100%;
}
div{
  display: flex;
  flex-direction: column;
  max-height: var(--image-height);
  max-width: var(--image-width);
}
a.frame{
  background-color: ${this.frameColor};
  padding: 2px;
  font-size: 0.5rem;
  line-height: 0.5rem;
  text-align: center;
}
img{
  max-height: var(--image-height);
  max-width: var(--image-width);
  object-fit: contain;
}
  max-height: calc( var(--image-height) - 0.5rem - 4px );
  max-width: calc( var(--image-width) - 4px );
}
   
`
  }
}

customElements.define('lwd-image', LwdImage);
class LwdInput extends LwdElement {
  constructor(props = {}) {
    super(undefined, props);
    this.shadowRoot.append(this.input = document.createElement('input'))
    this.autocomplete = document.createElement('div')
    this.autocomplete.className = 'autocomplete'
    this.input.addEventListener('input', (e) => this.value = e.target.value)
    this.addEventListener('input', this.fetchAutocompleteOptions)

    // setTimeout(() => 
    // this.autocompleteOptions = [
    //   { innerText: 'Lana (1234)', value: 'lana' },
    //   { innerText: 'Shantae (55)', value: 'shantae' },
    //   { innerText: 'amphibian (12872)', value: 'amphibian' },
    //   { innerText: 'sonic the hedgehog (series) (82674)', value: 'sonic_the_hedgehog_(series)' }]
    // , 8000)
  }

  static get observedAttributes() {
    return [...super.observedAttributes, 'value', 'type', '_autocomplete-options', '_autocomplete-fetch'];
  }
  get reRenderOnChange() {
    return [...super.reRenderOnChange, '_autocomplete-options']
  }

  get type() {
    return this.getAttribute('type')
  }
  set type(value) {
    this.setAttribute('type', value)
    this.input.setAttribute('type', value)
  }

  get value() {
    return this.getAttribute('value')
  }
  set value(value) {
    this.setAttribute('value', value)
    this.input.value = value
  }

  async fetchAutocompleteOptions(event) {
    if (!this.autocompleteFetch) return;
    const completeSearch = event.target.value
    const cursorPosition = this.input.selectionEnd
    let search = completeSearch.slice(0, cursorPosition).split(' ')
    search = search[search.length - 1]

    // console.log('fetchAutocompleteOptions', search,  await this.autocompleteFetch(search))
    this.autocompleteOptions = await this.autocompleteFetch(search)
  }

  defaultAutocompleteOnClick(event) {
    console.log('defaultAutocompleteOnClick', this,  this.lwdInput)
    // options trigger the event
    const lwdInput = this.lwdInput
    const searchWords = lwdInput.value.split(' ')
    const cursorPosition = lwdInput.input.selectionEnd
    const selectedValue = event.target.value


    const completedSearch = searchWords.reduce((completedSearch, word) =>
      completedSearch.length < cursorPosition && completedSearch.length + word.length + 1 > cursorPosition ?
        completedSearch + selectedValue + ' ' : completedSearch + word + ' '
      , '')

    lwdInput.value = completedSearch
    lwdInput.autocompleteOptions = undefined
    lwdInput.input.focus()
  }

  render() {
    super.render()

    this.autocomplete.innerHTML = ''
    if (!this.autocompleteOptions || this.autocompleteOptions?.length == 0) {
      this.autocomplete.remove()
    } else {
      this.shadowRoot.append(this.autocomplete)

      this.autocompleteOptions.forEach(({ innerText, value, className, onclick }) => {
        const option = document.createElement('div')
        option.lwdInput = this
        option.innerText = innerText
        option.value = value || innerText
        option.className = className || ''
        option.onclick = onclick || this.defaultAutocompleteOnClick
        this.autocomplete.append(option)
      })
    }
  }

  get styleSheet() {
    return `${super.styleSheet}
:host{
  display: inline-grid;
  color: white;
}
input, .autocomplete{
  background: #3d3d3d;
  width: 100%;
  border-radius: 0.4rem;
  outline: none;
  color: inherit;
}

input{
  border: #cacaca solid 1px;
  padding: 0 0.4rem;
}

.autocomplete{
  position: absolute;
  top: 100%;
  padding: 0.2rem 0;
}
.autocomplete > div{
  height: ${this.clientHeight}px;
  padding: 0 0.4rem;
  align-content: center;
}
.autocomplete > div:hover{
  background: #4400DD30
}
    `
  }
}
customElements.define('lwd-input', LwdInput);
class LwdPagination extends LwdElement {
  constructor(props = {}) {
    super(undefined, props);
    this.shadowRoot.append(new LwdSlot())

    this.buttonConstructor = props.buttonConstructor || this.defaultButtonConstructor
    this.page ||= 1
    this.lastPage ||= 1
    this.pagePad ||= 4
  }

  static get observedAttributes() {
    return [...super.observedAttributes, 'page', 'last-page', 'page-pad', '_button-constructor'];
  }
  get reRenderOnChange() {
    return [...super.reRenderOnChange, 'page', 'last-page', 'page-pad', '_button-constructor'];
  }

  set page(value) {
    if (value == this.page || value == 0 || value > this.lastPage) return;
    this.setAttribute('page', value)
  }

  defaultButtonConstructor(props = { innerText, onclick, active: false }) {
    return new LwdButton({ ...props, type: props.active ? 'outline' : 'ghost' })
  }

  get styleSheet() {
    return `${super.styleSheet}
    :host{
      display: grid;
      grid-template-columns: repeat(13, 1fr);
      grid-gap: 8px;
    }
`
  }

  render() {
    super.render()

    this.querySelectorAll('lwd-button').forEach((lwdButton) => lwdButton.remove())

    console.log('numberOfPage min', (this.pagePad * 2) + 1, this.lastPage)
    const numberOfPage = Math.min((this.pagePad * 2) + 1, this.lastPage)
    const firstPage = Math.max(1, Math.min(this.page - this.pagePad,  this.lastPage - numberOfPage + 1))

    Array.from({ length: numberOfPage }, (_, i) => firstPage + i).forEach((thisPage) => {
      this.append(this.buttonConstructor({ innerText: `${thisPage}`, onclick: () => this.page = thisPage, active: (thisPage == this.page) }))
    })

    this.renderArrows()
  }

  renderArrows() {
    this.prepend(this.buttonConstructor({ innerText: '<', onclick: () => this.page = parseInt(this.page) - 1 }))
    this.prepend(this.buttonConstructor({ innerText: '<<', onclick: () => this.page = 1 }))
    this.append(this.buttonConstructor({ innerText: '>', onclick: () => this.page = parseInt(this.page) + 1 }))
    this.append(this.buttonConstructor({ innerText: '>>', onclick: () => this.page = this.lastPage }))
  }
}

customElements.define('lwd-pagination', LwdPagination);
